import java.util.*;

class Solution {
  private int n, top;
  private int[] cntIn, cntOut;
  private long[] sumIn, sumOut, valueAt;

  public long maxSum(int[] nums, int k) {
    n = nums.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    Arrays.sort(order, (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b));
    int[] rank = new int[n];
    valueAt = new long[n + 1];
    for (int r = 0; r < n; r++) {
      rank[order[r]] = r + 1;
      valueAt[r + 1] = nums[order[r]];
    }
    top = Integer.highestOneBit(n);
    cntIn = new int[n + 1];
    cntOut = new int[n + 1];
    sumIn = new long[n + 1];
    sumOut = new long[n + 1];
    long best = Long.MIN_VALUE;
    for (int l = 0; l < n; l++) {
      Arrays.fill(cntIn, 0);
      Arrays.fill(sumIn, 0);
      Arrays.fill(cntOut, 0);
      Arrays.fill(sumOut, 0);
      long totalOut = 0, inside = 0;
      for (int i = 0; i < n; i++) {
        add(cntOut, sumOut, rank[i], 1, nums[i]);
        totalOut += nums[i];
      }
      for (int r = l; r < n; r++) {
        add(cntOut, sumOut, rank[r], -1, nums[r]);
        add(cntIn, sumIn, rank[r], 1, nums[r]);
        totalOut -= nums[r];
        inside += nums[r];
        int outCount = n - (r - l + 1);
        // swapping the t smallest inside for the t largest outside gains exactly while those inside values rank
        // among the outCount globally smallest, so the best t is the number of inside elements with rank <= outCount
        int t = Math.min(k, prefixCount(cntIn, outCount));
        long gain = 0;
        if (t > 0) gain = (totalOut - smallestSum(cntOut, sumOut, outCount - t)) - smallestSum(cntIn, sumIn, t);
        best = Math.max(best, inside + gain);
      }
    }
    return best;
  }

  private void add(int[] cnt, long[] sum, int pos, int c, long v) {
    for (; pos <= n; pos += pos & -pos) {
      cnt[pos] += c;
      sum[pos] += c * v;
    }
  }

  private int prefixCount(int[] cnt, int pos) {
    int s = 0;
    for (; pos > 0; pos -= pos & -pos) s += cnt[pos];
    return s;
  }

  // sum of the t smallest stored values (each rank holds at most one value)
  private long smallestSum(int[] cnt, long[] sum, int t) {
    if (t <= 0) return 0;
    int pos = 0, rem = t;
    long acc = 0;
    for (int pw = top; pw > 0; pw >>= 1) {
      if (pos + pw <= n && cnt[pos + pw] < rem) {
        pos += pw;
        rem -= cnt[pos];
        acc += sum[pos];
      }
    }
    return acc + rem * valueAt[pos + 1];
  }
}
